atts.custom_css:
selector{align-self:center;width:auto;}
selector::before { content:"";position:absolute;top:0px;right:0px;bottom:0px;left:0px;inset:0px;transition:opacity 0.3s;transition-property:opacity;transition-duration:0.3s;transition-timing-function:ease;opacity:0; }
selector::after { content:"";position:absolute;top:-50%;left:-50%;transition:opacity 0.4s;transition-property:opacity;transition-duration:0.4s;transition-timing-function:ease;background-color:initial;background-image:conic-gradient(transparent 30%, oklch(0.85 0.1 45 / 0.15) 40%, transparent 50%);opacity:0;width:200%;height:200%;animation:4s linear 0s infinite normal none running shimmer-spin;animation-name:shimmer-spin; }
selector:hover { background-color:oklch(0.85 0.08 45 / 0.15) !important;background-image:initial !important;border-color:oklch(0.85 0.1 45 / 0.5) !important; }
selector:hover::before { opacity:1 !important; }
:where(selector){text-align:center;transition:border-radius 0.6s, border-color 0.3s, background 0.3s;}

selector{align-self:flex-start;width:auto;}
selector::before { content:"";position:absolute;top:0px;right:0px;bottom:0px;left:0px;inset:0px;transition:opacity 0.3s;transition-property:opacity;transition-duration:0.3s;transition-timing-function:ease;opacity:0; }
selector::after { content:"";position:absolute;top:-50%;left:-50%;transition:opacity 0.4s;transition-property:opacity;transition-duration:0.4s;transition-timing-function:ease;background-color:initial;background-image:conic-gradient(transparent 30%, oklch(0.85 0.1 45 / 0.15) 40%, transparent 50%);opacity:0;width:200%;height:200%;animation:4s linear 0s infinite normal none running shimmer-spin;animation-name:shimmer-spin; }
selector:hover { background-color:oklch(0.85 0.08 45 / 0.15) !important;background-image:initial !important;border-color:oklch(0.85 0.1 45 / 0.5) !important; }
selector:hover::before { opacity:1 !important; }
:where(selector){transition:border-radius 0.6s, border-color 0.3s, background 0.3s;}
